mapper.select:
select count(*) from
(select distinct b.report_id as report_id,a.platform as platform,a.analysis_date as analysis_date,a.barcode as
barcode,a.subbarcode as subbarcode,
ifnull(b.product_name,a.product_name) as product_name,c.disease_class_chinese as primary_cancer,b.chem_cancer as chem_cancer,
b.analyzer as analyzer,b.checked_date as checked_date,
b.checked_by as checked_by,b.report_time as report_date,b.report_filename as report_filename,b.report_file_path
as report_file_path,b.status as status
from ((data_file_status a left join analysis_report b on(((b.subbarcode = a.subbarcode) and (b.platform =
a.platform) and (b.analysis_date = a.analysis_date))))
left join disease_class c on((b.primary_cancer_id = c.class_id)))

	and a.subbarcode <> ''

		and a.platform=#{platform}


		and a.analysis_date=#{analysis_date}


		and a.subbarcode=#{subbarcode}


		and b.status=#{status}


		and (b.product_name =#{product_name} or (b.product_name is null and a.product_name=#{product_name}))


		and a.subbarcode in

			#{item}



) b

select distinct b.report_id as report_id,a.platform as platform,a.analysis_date as analysis_date,a.barcode as barcode,a.subbarcode as subbarcode,
ifnull(b.product_name,a.product_name) as product_name,c.disease_class_chinese as primary_cancer,b.chem_cancer as chem_cancer,b.analyzer as analyzer,b.checked_date as checked_date,
b.checked_by as checked_by,b.report_time as report_date,b.report_filename as report_filename,b.report_file_path as report_file_path,b.status as status
from ((data_file_status a left join analysis_report b on(((b.subbarcode = a.subbarcode) and (b.platform = a.platform) and (b.analysis_date = a.analysis_date))))
left join disease_class c on((b.primary_cancer_id = c.class_id)))

	and a.subbarcode <> ''

		and a.platform=#{platform}


		and a.analysis_date=#{analysis_date}


		and a.subbarcode=#{subbarcode}


		and b.status=#{status}


		and (b.product_name =#{product_name} or (b.product_name is null and a.product_name=#{product_name}))


		and a.subbarcode in

			#{item}



order by b.report_time
limit #{pageNo},#{pageSize}

select distinct a.subbarcode
from ((data_file_status a left join analysis_report b on(((b.subbarcode = a.subbarcode) and (b.platform = a.platform) and (b.analysis_date = a.analysis_date)))))

	and a.subbarcode <> ''

		and a.platform=#{platform}

select distinct ifnull(b.product_name,a.product_name) as product_name
from ((data_file_status a left join analysis_report b on(((b.subbarcode = a.subbarcode) and (b.platform = a.platform) and (b.analysis_date = a.analysis_date)))))

	and a.subbarcode <> ''

		and a.platform=#{platform}
